export const CONSTITUENCY_BY_NAME = new Map<string, AssemblyConstituency>(
  ASSEMBLY_CONSTITUENCIES.map((c) => [c.name.toLowerCase(), c])
);

export function getConstituency(name: string): AssemblyConstituency | undefined {
  if (!name) return undefined;
  return CONSTITUENCY_BY_NAME.get(name.trim().toLowerCase());
}

export function getConstituenciesForDivision(divisionName: string): AssemblyConstituency[] {
  if (!divisionName) return ASSEMBLY_CONSTITUENCIES;
  return ASSEMBLY_CONSTITUENCIES.filter(
    (c) => c.division.toLowerCase() === divisionName.trim().toLowerCase()
  );
}
